def is_prime(n):
    """
    Kiểm tra xem một số nguyên dương n có phải là số nguyên tố hay không.

    Args:
        n (int): Số cần kiểm tra.

    Returns:
        bool: True nếu n là số nguyên tố, False nếu ngược lại.
    """
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def main():
    try:
        user_input = input("Nhập một số nguyên dương để kiểm tra: ")
        number = int(user_input)

        if is_prime(number):
            print(f"{number} là số nguyên tố.")
        else:
            print(f"{number} không phải là số nguyên tố.")

    except ValueError:
        print("Lỗi: Vui lòng nhập một số nguyên hợp lệ.")
