using System.Windows;

namespace SimpleCalculator
{
    public partial class MainWindow : Window
    {
        private double _currentValue = 0;
        private double _storedValue = 0;
        private string _operation = "";
        private bool _isNewEntry = true;

        public MainWindow()
        {
            InitializeComponent();
        }

        private void UpdateDisplay()
        {
            DisplayTextBox.Text = _currentValue.ToString();
        }

        private void NumberButton_Click(object sender, RoutedEventArgs e)
        {
            if (sender is Button button)
            {
                string digit = button.Content.ToString();
                if (_isNewEntry)
                {
                    _currentValue = 0;
                    _isNewEntry = false;
                }

                // Xử lý nhập số thập phân hoặc số nguyên
                if (digit == ".")
                {
                    if (!_currentValue.ToString().Contains("."))
                    {
                        DisplayTextBox.Text += digit;
                        _currentValue = double.Parse(DisplayTextBox.Text);
                    }
                }
                else
                {
                    DisplayTextBox.Text = DisplayTextBox.Text == "0" ? digit : DisplayTextBox.Text + digit;
                    _currentValue = double.Parse(DisplayTextBox.Text);
                }
            }
        }

        private void DecimalButton_Click(object sender, RoutedEventArgs e)
        {
            if (_isNewEntry)
            {
                DisplayTextBox.Text = "0.";
                _isNewEntry = false;
            }
            else if (!DisplayTextBox.Text.Contains("."))
            {
                DisplayTextBox.Text += ".";
            }
        }

        private void ClearButton_Click(object sender, RoutedEventArgs e)
        {
            _currentValue = 0;
            _storedValue = 0;
            _operation = "";
            _isNewEntry = true;
            DisplayTextBox.Text = "0";
        }

        private void ClearEntryButton_Click(object sender, RoutedEventArgs e)
        {
            _currentValue = 0;
            _isNewEntry = true;
            DisplayTextBox.Text = "0";
        }

        private void AddButton_Click(object sender, RoutedEventArgs e) => SetOperation("+");
        private void SubtractButton_Click(object sender, RoutedEventArgs e) => SetOperation("-");
        private void MultiplyButton_Click(object sender, RoutedEventArgs e) => SetOperation("*");
        private void DivideButton_Click(object sender, RoutedEventArgs e) => SetOperation("/");

        private void SetOperation(string op)
        {
            if (_operation != "" && !_isNewEntry)
            {
                Calculate();
            }
            _storedValue = _currentValue;
            _operation = op;
            _isNewEntry = true;
        }

        private void EqualsButton_Click(object sender, RoutedEventArgs e)
        {
            Calculate();
            _operation = "";
            _isNewEntry = true;
        }

        private void Calculate()
        {
            switch (_operation)
            {
                case "+":
                    _currentValue = _storedValue + _currentValue;
                    break;
                case "-":
                    _currentValue = _storedValue - _currentValue;
                    break;
                case "*":
                    _currentValue = _storedValue * _currentValue;
                    break;
                case "/":
                    if (_currentValue != 0)
                        _currentValue = _storedValue / _currentValue;
                    else
                        DisplayTextBox.Text = "Lỗi chia 0";
                    break;
            }
            UpdateDisplay();
        }

        private void PercentButton_Click(object sender, RoutedEventArgs e)
        {
            _currentValue = _currentValue / 100;
            UpdateDisplay();
            _isNewEntry = true;
        }

        private void SqrtButton_Click(object sender, RoutedEventArgs e)
        {
            if (_currentValue >= 0)
            {
                _currentValue = Math.Sqrt(_currentValue);
                UpdateDisplay();
                _isNewEntry = true;
            }
            else
            {
                DisplayTextBox.Text = "Lỗi số âm";
            }
        }
